import test from 'node:test';
import assert from 'node:assert/strict';
import { batches } from '../src/batches.js';

const validCases = [
  { total: 0, size: 1, expected: 0 },
  { total: 0, size: 7, expected: 0 },
  { total: 7, size: 1, expected: 7 },
  { total: 12, size: 4, expected: 3 },
  { total: 13, size: 4, expected: 4 },
  { total: 3, size: 4, expected: 1 },
  { total: 4, size: 4, expected: 1 },
  { total: 5, size: 4, expected: 2 },
];

for (const { total, size, expected } of validCases) {
  test(`batches(${total}, ${size}) requires exactly ${expected} batches`, () => {
    assert.strictEqual(batches(total, size), expected);
  });
}

for (const total of [-1, 1.5]) {
  test(`rejects invalid total ${total} with a valid size`, () => {
    assert.throws(() => batches(total, 4), RangeError);
  });
}

for (const size of [-1, 0, 1.5]) {
  test(`rejects invalid size ${size} with a positive total`, () => {
    assert.throws(() => batches(5, size), RangeError);
  });

  test(`zero total does not bypass rejection of invalid size ${size}`, () => {
    assert.throws(() => batches(0, size), RangeError);
  });
}

